@file:OptIn(ExperimentalUuidApi::class)

package cityinfo.io.core.cache

import java.util.concurrent.ConcurrentHashMap
import kotlin.uuid.ExperimentalUuidApi
import kotlin.uuid.Uuid

/**
 * Глобальный менеджер кэш-инстансов, созданных через [CacheBuilder] и обёрнутых в [CacheInstance].
 *
 * Используется для централизованного управления всеми кэшами, зарегистрированными в процессе выполнения приложения.
 * Каждый [CacheInstance] автоматически регистрируется в [instances] при создании.
 */
object CacheManager {

    /**
     * Коллекция всех зарегистрированных кэш-инстансов.
     *
     * Ключом является уникальный [Uuid], сгенерированный при создании каждого [CacheInstance].
     * Это поле предназначено для внутреннего использования и не должно модифицироваться напрямую извне.
     */
    internal val instances = ConcurrentHashMap<Uuid, CacheInstance<*, *>>()

    /**
     * Инвалидирует (очищает) все кэш-инстансы, зарегистрированные в [instances].
     *
     * Полезно для ситуаций, когда необходимо сбросить все кэши, например, при выходе пользователя,
     * сбросе состояния приложения или при сбоях, требующих повторной инициализации данных.
     */
    fun invalidateAll() {
        instances.forEach { (_, cache) ->
            cache.invalidateAll()
        }
    }

    /**
     * Возвращает множество всех UUID, зарегистрированных в менеджере кэшей.
     *
     * Каждый UUID соответствует уникальному [CacheInstance], созданному в приложении.
     * Это может быть полезно для отладки, мониторинга или управления конкретными кэшами.
     *
     * @return Набор всех UUID зарегистрированных кэшей.
     */
    fun allCacheIds(): Set<Uuid> = instances.keys

    /**
     * Возвращает список всех активных кэшей, зарегистрированных в [CacheManager].
     *
     * Каждый кэш представлен экземпляром [CacheInstance], хранящимся в [instances].
     *
     * @return список всех текущих кэш-экземпляров.
     */
    fun allCacheInstances(): List<CacheInstance<*, *>> = instances.values.toList()

    /**
     * Возвращает общее количество кэш-инстансов, зарегистрированных в [CacheManager].
     *
     * Может использоваться для анализа или проверки корректности регистрации кэшей.
     *
     * @return Количество зарегистрированных [CacheInstance].
     */
    fun count(): Int = instances.size

    /**
     * Полностью очищает все зарегистрированные кэши и удаляет их из менеджера.
     *
     * Эта операция сначала вызывает [invalidateAll], чтобы очистить все значения внутри каждого [CacheInstance],
     * а затем полностью удаляет все ссылки на кэши из внутреннего хранилища [instances].
     *
     * Используется в ситуациях, когда требуется полный сброс состояния кэш-системы, например:
     * - при выходе пользователя из приложения,
     * - при перезапуске среды,
     * - в тестах для очистки между кейсами.
     */
    fun clearAll() {
        invalidateAll()
        instances.clear()
    }

    /**
     * Устанавливает флаг активности для всех зарегистрированных кэшей.
     *
     * Если [isEnabled] установлен в `false`, все кэши временно отключаются — операции чтения возвращают `null`
     * или вызывают загрузчик напрямую, а записи игнорируются.
     * При установке в `true` — кэши снова начинают работать в обычном режиме.
     *
     * @param isEnabled Флаг активности: `true` — включить все кэши, `false` — отключить.
     */
    fun setEnabledCache(isEnabled: Boolean) {
        instances.forEach { it.value.setEnabled(isEnabled) }
    }
}
